    """Clamp val to the closed interval [lo, hi]."""
    return max(lo, min(val, hi))

pub const fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b != 0 {
        let t = b;
        b = a % b;
        a = t;
    }
    a
}

