import threading

class Singleton:
    _instance = None
    _lock = threading.Lock()
    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

pub struct AtomicTokenBucket { tokens: AtomicU64, last_ns: AtomicU64 }
impl AtomicTokenBucket {
    pub fn try_acquire(&self, cost: u64) -> bool {
        self.tokens.fetch_update(Ordering::AcqRel, Ordering::Acquire, |cur| cur.checked_sub(cost)).is_ok()
    }
}
